FuncDef.Code:
mat2 cameraOpDefault_Rot(float a)
{
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

void cameraOpDefault(inout vec3 ro, inout vec3 rd, in vec2 fragCoord)
{
    // out
    vec3 pos = vec3(0.0);
    vec3 ray = vec3(0.0);

    // in
    vec2 rotation       = vec2(cameraRotationPitch, cameraRotationYaw);
    float distance      = cameraDistanceToTarget;
    float zoom          = cameraZoom;

    vec2 c = cos(rotation);
    vec4 s;
    s.xy   = sin(rotation);
    s.zw = -s.xy;

    // ray in view space
    ray.xy = fragCoord.xy - iResolution.xy*.5;
    ray.z = iResolution.y*zoom;

    // roll rotation
    //ray.xy *= cameraOpDefault_Rot(cameraRotationRoll);
    ray.xy = SDFG_MUL(cameraOpDefault_Rot(cameraRotationRoll), ray.xy);

    ray = normalize(ray);

    // rotate ray
    ray.yz = ray.yz*c.xx + ray.zy*s.zx;
    ray.xz = ray.xz*c.yy + ray.zx*s.yw;

    // position camera
    pos = cameraTargetPosition - distance*vec3(c.x*s.y,s.z,c.x*c.y);

    ro = pos;
    rd = ray;
}
